#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *cr, *cc;
    int *fr, *fc;
    int cn, fn, walls;
} Region;

static int containVirus(int **grid, int m, int n) {
    int total = 0;
    int dr[4] = {1,-1,0,0}, dc[4] = {0,0,1,-1};

    while (1) {
        int **seen = (int**)calloc((size_t)m, sizeof(int*));
        for (int i=0; i<m; ++i) seen[i] = (int*)calloc((size_t)n, sizeof(int));
        Region *regions = NULL;
        int regionCount = 0;

        for (int r=0; r<m; ++r) {
            for (int c=0; c<n; ++c) {
                if (grid[r][c] != 1 || seen[r][c]) continue;
                Region reg;
                reg.cr = (int*)malloc((size_t)m*n*sizeof(int));
                reg.cc = (int*)malloc((size_t)m*n*sizeof(int));
                reg.fr = (int*)malloc((size_t)m*n*sizeof(int));
                reg.fc = (int*)malloc((size_t)m*n*sizeof(int));
                reg.cn = reg.fn = reg.walls = 0;
                int *qx = (int*)malloc((size_t)m*n*sizeof(int));
                int *qy = (int*)malloc((size_t)m*n*sizeof(int));
                int *marked = (int*)calloc((size_t)m*n, sizeof(int));
                int head=0, tail=0;
                qx[tail]=r; qy[tail++]=c; seen[r][c]=1;

                while (head < tail) {
                    int x=qx[head], y=qy[head++];
                    reg.cr[reg.cn]=x; reg.cc[reg.cn++]=y;
                    for (int k=0;k<4;++k) {
                        int nx=x+dr[k], ny=y+dc[k];
                        if (nx<0 || nx>=m || ny<0 || ny>=n) continue;
                        if (grid[nx][ny]==1 && !seen[nx][ny]) {
                            seen[nx][ny]=1; qx[tail]=nx; qy[tail++]=ny;
                        } else if (grid[nx][ny]==0) {
                            reg.walls++;
                            int id=nx*n+ny;
                            if (!marked[id]) {
                                marked[id]=1; reg.fr[reg.fn]=nx; reg.fc[reg.fn++]=ny;
                            }
                        }
                    }
                }
                free(qx); free(qy); free(marked);
                regions=(Region*)realloc(regions,(size_t)(regionCount+1)*sizeof(Region));
                regions[regionCount++]=reg;
            }
        }

        for (int i=0;i<m;++i) free(seen[i]);
        free(seen);
        if (regionCount==0) { free(regions); return total; }

        int chosen=0;
        for (int i=1;i<regionCount;++i) if (regions[i].fn > regions[chosen].fn) chosen=i;
        if (regions[chosen].fn==0) {
            for(int i=0;i<regionCount;++i){free(regions[i].cr);free(regions[i].cc);free(regions[i].fr);free(regions[i].fc);}
            free(regions); return total;
        }

        total += regions[chosen].walls;
        for (int z=0; z<regions[chosen].cn; ++z) grid[regions[chosen].cr[z]][regions[chosen].cc[z]]=-1;
        for (int i=0; i<regionCount; ++i) if (i!=chosen)
            for (int z=0; z<regions[i].fn; ++z) grid[regions[i].fr[z]][regions[i].fc[z]]=1;

        for(int i=0;i<regionCount;++i){free(regions[i].cr);free(regions[i].cc);free(regions[i].fr);free(regions[i].fc);}
        free(regions);
    }
}

static void parseGrid(const char *s, int rows[50][50], int *m, int *n) {
    int depth=0, r=-1, c=-1, maxc=0;
    for (int i=0; s[i]; ++i) {
        if (s[i]=='[') { ++depth; if (depth==3) { ++r; c=-1; } }
        else if (s[i]==']') { --depth; }
        else if ((s[i]=='0' || s[i]=='1') && depth==3) { rows[r][++c]=s[i]-'0'; if(c+1>maxc) maxc=c+1; }
    }
    *m=r+1; *n=maxc;
}

