class Solution {
public:
    int containVirus(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size(), total = 0;
        const int dr[4] = {1, -1, 0, 0};
        const int dc[4] = {0, 0, 1, -1};

        while (true) {
            vector<vector<int>> seen(m, vector<int>(n, 0));
            vector<vector<pair<int,int>>> cells;
            vector<set<pair<int,int>>> frontiers;
            vector<int> walls;

            for (int r = 0; r < m; ++r) {
                for (int c = 0; c < n; ++c) {
                    if (grid[r][c] != 1 || seen[r][c]) continue;
                    vector<pair<int,int>> cur;
                    set<pair<int,int>> frontier;
                    int w = 0;
                    queue<pair<int,int>> q;
                    q.push({r,c});
                    seen[r][c] = 1;
                    while (!q.empty()) {
                        auto [x,y] = q.front(); q.pop();
                        cur.push_back({x,y});
                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dr[k], ny = y + dc[k];
                            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                            if (grid[nx][ny] == 1 && !seen[nx][ny]) {
                                seen[nx][ny] = 1;
                                q.push({nx,ny});
                            } else if (grid[nx][ny] == 0) {
                                frontier.insert({nx,ny});
                                ++w;
                            }
                        }
                    }
                    cells.push_back(move(cur));
                    frontiers.push_back(move(frontier));
                    walls.push_back(w);
                }
            }

            if (cells.empty()) return total;
            int chosen = 0;
            for (int i = 1; i < (int)cells.size(); ++i)
                if (frontiers[i].size() > frontiers[chosen].size()) chosen = i;
            if (frontiers[chosen].empty()) return total;

            total += walls[chosen];
            for (auto [x,y] : cells[chosen]) grid[x][y] = -1;
            for (int i = 0; i < (int)cells.size(); ++i) {
                if (i == chosen) continue;
                for (auto [x,y] : frontiers[i]) grid[x][y] = 1;
            }
        }
    }
};

