class Solution {
    public int containVirus(int[][] grid) {
        int m = grid.length, n = grid[0].length, total = 0;
        int[][] d = {{1,0},{-1,0},{0,1},{0,-1}};

        while (true) {
            boolean[][] seen = new boolean[m][n];
            List<List<int[]>> regions = new ArrayList<>();
            List<Set<Integer>> frontiers = new ArrayList<>();
            List<Integer> wallCounts = new ArrayList<>();

            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] != 1 || seen[r][c]) continue;
                    ArrayDeque<int[]> q = new ArrayDeque<>();
                    List<int[]> cells = new ArrayList<>();
                    Set<Integer> frontier = new HashSet<>();
                    int walls = 0;
                    q.add(new int[]{r,c});
                    seen[r][c] = true;
                    while (!q.isEmpty()) {
                        int[] cur = q.removeFirst();
                        int x = cur[0], y = cur[1];
                        cells.add(cur);
                        for (int[] dir : d) {
                            int nx = x + dir[0], ny = y + dir[1];
                            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                            if (grid[nx][ny] == 1 && !seen[nx][ny]) {
                                seen[nx][ny] = true;
                                q.addLast(new int[]{nx,ny});
                            } else if (grid[nx][ny] == 0) {
                                frontier.add(nx * n + ny);
                                walls++;
                            }
                        }
                    }
                    regions.add(cells);
                    frontiers.add(frontier);
                    wallCounts.add(walls);
                }
            }

            if (regions.isEmpty()) return total;
            int chosen = 0;
            for (int i = 1; i < regions.size(); i++)
                if (frontiers.get(i).size() > frontiers.get(chosen).size()) chosen = i;
            if (frontiers.get(chosen).isEmpty()) return total;

            total += wallCounts.get(chosen);
            for (int[] cell : regions.get(chosen)) grid[cell[0]][cell[1]] = -1;
            for (int i = 0; i < regions.size(); i++) {
                if (i == chosen) continue;
                for (int key : frontiers.get(i)) grid[key / n][key % n] = 1;
            }
        }
    }
}

