class Solution:
    def containVirus(self, isInfected: List[List[int]]) -> int:
        m = len(isInfected)
        n = len(isInfected[0])
        total = 0
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while True:
            seen = [[False] * n for _ in range(m)]
            regions = []

            for r in range(m):
                for c in range(n):
                    if isInfected[r][c] != 1 or seen[r][c]:
                        continue
                    stack = [(r, c)]
                    seen[r][c] = True
                    cells = []
                    frontier = set()
                    walls = 0

                    while stack:
                        x, y = stack.pop()
                        cells.append((x, y))
                        for dx, dy in directions:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < m and 0 <= ny < n:
                                if isInfected[nx][ny] == 1 and not seen[nx][ny]:
                                    seen[nx][ny] = True
                                    stack.append((nx, ny))
                                elif isInfected[nx][ny] == 0:
                                    frontier.add((nx, ny))
                                    walls += 1

                    regions.append((len(frontier), walls, cells, frontier))

            if not regions:
                return total

            chosen = max(range(len(regions)), key=lambda i: regions[i][0])
            if regions[chosen][0] == 0:
                return total

            total += regions[chosen][1]

            for x, y in regions[chosen][2]:
                isInfected[x][y] = -1

            for i, (_, _, _, frontier) in enumerate(regions):
                if i == chosen:
                    continue
                for x, y in frontier:
                    isInfected[x][y] = 1

