    static List<String> rows(String s) {
        List<String> out = new ArrayList<>();
        int depth = 0, start = -1;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '[') {
                depth++;
                if (depth == 3) start = i;
            } else if (ch == ']') {
                if (depth == 3) out.add(s.substring(start, i + 1));
                depth--;
            }
        }
        return out;
    }

